/**
 * WHY /legacy specifically: plain 'expo-file-system' in this SDK version
 * is the new File/Directory API, and copyAsync/cacheDirectory are the old
 * function-based API's names. Importing them from the plain path still
 * resolves at compile time but triggers a deprecation shim that throws at
 * call time instead of just warning. audioStorage.ts already standardized
 * on /legacy for exactly this reason.
 */
import { cacheDirectory, copyAsync } from 'expo-file-system/legacy';
import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';

import type { Idea } from '@/src/types';

/**
 * Exports a set of search results as a PDF, showing exactly the two spec-
 * approved fields plus the AI Core Insight - Source, Thought, AI Core Insight
 * - plus the thought ID and category. Nothing else: no audio, no raw
 * metadata, no fields belonging to the deferred AI Intelligence layer.
 *
 * WHY the colors and layout below are pulled from src/theme/tokens.ts rather
 * than invented for this file: the point of the redesign was for the export
 * to actually look like it came from Think Tap, not a generic report
 * template. Hex values (background #F0F5FF, primary #0F1C3F, secondary
 * #2563EB, and the per-category palette) are copied directly from the app's
 * own tokens, not approximated.
 *
 * WHY the bare icon, not the full logo-with-wordmark image: the header now
 * shows "Tasset" as its own text label, matching the in-app screen header's
 * own title/subtitle pattern (ideas.tsx's tx('myArchive') subtitle reads
 * "My Thoughts") rather than the app's full product wordmark. Embedding
 * thinktap-logo.png (which already has "ThinkTap" baked into the image
 * itself) would have shown two different labels side by side. The icon is
 * cropped to its actual content bounding box before use - the source file,
 * android-icon-foreground.png, has substantial transparent padding built in
 * for Android's adaptive-icon mask system, which would otherwise render the
 * mark oddly small and off-center inside the header.
 *
 * WHY the header background is a light tint, not dark navy: it needs to
 * read clearly against the dark "Tasset" label text sitting next to it.
 */

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const BRAND = {
  background: '#F0F5FF',
  primary: '#0F1C3F',
  onPrimary: '#FFFFFF',
  secondary: '#2563EB',
  secondarySoft: '#EFF6FF',
  onSurface: '#152238',
  onSurfaceVariant: '#4B5B76',
  border: '#D6E0F0',
};

const CATEGORY_COLORS: Record<string, { bg: string; soft: string }> = {
  Movies: { bg: '#3B82F6', soft: '#DBEAFE' },
  Songs: { bg: '#6366F1', soft: '#E0E7FF' },
  Books: { bg: '#0EA5E9', soft: '#E0F2FE' },
  Business: { bg: '#1D4ED8', soft: '#DBEAFE' },
  Scripts: { bg: '#4F46E5', soft: '#E0E7FF' },
  Design: { bg: '#0284C7', soft: '#E0F2FE' },
  Music: { bg: '#2563EB', soft: '#DBEAFE' },
};

function categoryColorFor(category: string) {
  return CATEGORY_COLORS[category] ?? { bg: BRAND.secondary, soft: BRAND.secondarySoft };
}

/**
 * WHY this fallback chain: the backend moved from a five-field shape to the
 * spec-correct one (source_of_inspiration, ai_core_insight). Until an idea
 * has been reprocessed under the new shape, analysis.thought is what the app
 * already treats as the Insight display value; idea.summary is the offline/
 * local fallback used when no analysis exists at all.
 */
function coreInsightFor(idea: Idea): string {
  return (idea.analysis?.thought || idea.summary || '').trim();
}

/** android-icon-foreground.png, cropped to its content bounds (see the WHY
 * note above) and base64-encoded. */
const ICON_BASE64 =
  '';

function thoughtCardHtml(idea: Idea, index: number, total: number): string {
  const source = escapeHtml((idea.analysis?.sourceOfInspiration || '').trim() || '—');
  const thought = escapeHtml((idea.transcript || '').trim() || '—');
  const insight = escapeHtml(coreInsightFor(idea) || '—');
  const category = escapeHtml(idea.category || 'Uncategorized');
  const tint = categoryColorFor(idea.category || '');
  const date = idea.createdAt
    ? new Date(idea.createdAt).toLocaleDateString(undefined, {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
      })
    : '';

  return `
    <div class="card">
      <div class="card-top">
        <span class="category-badge" style="background:${tint.soft}; color:${tint.bg};">${category}</span>
        <span class="card-counter">Thought ${index + 1} of ${total}</span>
      </div>
      ${date ? `<div class="card-meta-row"><span class="date">${date}</span></div>` : ''}

      <div class="field">
        <div class="label label-source">Source of Inspiration</div>
        <div class="value ${source === '—' ? 'value-empty' : ''}">${source}</div>
      </div>
      <div class="field">
        <div class="label label-thought">Thought</div>
        <div class="value">${thought}</div>
      </div>
      <div class="field field-insight">
        <div class="label label-insight">✦ AI Core Insight</div>
        <div class="value ${insight === '—' ? 'value-empty' : ''}">${insight}</div>
      </div>
    </div>
  `;
}

function reportHtml(ideas: Idea[]): string {
  const generatedAt = new Date().toLocaleString();
  const cards = ideas.map((idea, i) => thoughtCardHtml(idea, i, ideas.length)).join('\n');

  return `
    <html>
      <head>
        <meta charset="utf-8" />
        <style>
          @page {
            margin: 0;
            @bottom-center {
              content: "Think Tap · Page " counter(page) " of " counter(pages);
              font-size: 9px;
              color: ${BRAND.onSurfaceVariant};
            }
          }
          * { box-sizing: border-box; }
          body {
            font-family: -apple-system, Helvetica, Arial, sans-serif;
            color: ${BRAND.onSurface};
            background: ${BRAND.background};
            margin: 0;
            padding: 0;
          }

          .header {
            background: ${BRAND.secondarySoft};
            padding: 22px 32px 20px;
            display: flex;
            align-items: center;
            gap: 14px;
          }
          .header img.icon {
            height: 48px;
            width: auto;
            object-fit: contain;
          }
          .header .label-stack { display: flex; flex-direction: column; }
          .header .app-label {
            margin: 0;
            font-size: 22px;
            font-weight: 700;
            letter-spacing: 0.2px;
            color: ${BRAND.primary};
          }
          .header .subtitle {
            margin-top: 1px;
            font-size: 12px;
            color: ${BRAND.onSurfaceVariant};
          }

          .meta-band {
            background: ${BRAND.secondarySoft};
            padding: 14px 32px;
            font-size: 12px;
            color: ${BRAND.onSurfaceVariant};
          }

          .content { padding: 24px 32px 40px; }

          .card {
            background: #FFFFFF;
            border: 1px solid ${BRAND.border};
            border-radius: 14px;
            padding: 18px 20px;
            margin-bottom: 18px;
            page-break-inside: avoid;
          }
          .card-top {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 6px;
          }
          .category-badge {
            display: inline-block;
            font-size: 10px;
            font-weight: 700;
            letter-spacing: 0.5px;
            text-transform: uppercase;
            padding: 4px 10px;
            border-radius: 999px;
          }
          .card-counter {
            font-size: 10px;
            color: ${BRAND.onSurfaceVariant};
          }
          .card-meta-row {
            display: flex;
            gap: 12px;
            margin-bottom: 14px;
          }
          .date {
            font-size: 9px;
            color: #9CA3AF;
          }

          .field { margin-bottom: 12px; }
          .field:last-child { margin-bottom: 0; }
          .label {
            font-size: 10px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 4px;
          }
          .label-source { color: #0EA5E9; }
          .label-thought { color: ${BRAND.secondary}; }
          .label-insight { color: #7C3AED; }
          .value {
            font-size: 12.5px;
            line-height: 1.55;
            white-space: pre-wrap;
            color: ${BRAND.onSurface};
          }
          .value-empty { color: #B0B9C9; font-style: italic; }

          .field-insight {
            background: #F5F3FF;
            border-left: 3px solid #7C3AED;
            border-radius: 8px;
            padding: 10px 12px;
            margin-top: 4px;
          }
        </style>
      </head>
      <body>
        <div class="header">
          <img class="icon" src="data:image/png;base64,${ICON_BASE64}" />
          <div class="label-stack">
            <div class="app-label">Tasset</div>
            <div class="subtitle">My Thoughts</div>
          </div>
        </div>
        <div class="meta-band">
          ${ideas.length} thought${ideas.length === 1 ? '' : 's'} &nbsp;·&nbsp;
          Generated ${escapeHtml(generatedAt)}
        </div>
        <div class="content">
          ${cards}
        </div>
      </body>
    </html>
  `;
}

/**
 * Generates the PDF and opens the system share sheet. Throws on failure -
 * callers should catch and show a toast rather than let this throw reach the
 * user unhandled.
 */
export async function exportThoughtsPdf(ideas: Idea[]): Promise<void> {
  if (ideas.length === 0) {
    throw new Error('No results to export.');
  }

  const html = reportHtml(ideas);
  const { uri } = await Print.printToFileAsync({ html, base64: false });

  // WHY moved rather than shared from the cache path directly: Print writes
  // to a temp cache location with a generic name; giving it a real filename
  // makes the share sheet and the saved file itself readable at a glance.
  const fileName = `thinktap-search-${Date.now()}.pdf`;
  const destination = `${cacheDirectory}${fileName}`;
  await copyAsync({ from: uri, to: destination });

  const canShare = await Sharing.isAvailableAsync();
  if (!canShare) {
    throw new Error('Sharing is not available on this device.');
  }

  await Sharing.shareAsync(destination, {
    mimeType: 'application/pdf',
    dialogTitle: 'Share your Think Tap search results',
  });
}
